// Node 18+ (built-in fetch). Run: BOT_TOKEN=xxx node bot.js
const API = `https://api.telegram.org/bot${process.env.BOT_TOKEN}`;
let offset = 0;

async function call(method, body) {
  const res = await fetch(`${API}/${method}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  if (!data.ok) console.error(method, data.error_code, data.description);
  return data;
}

async function handle(req) {
  const source = req.invite_link?.name || 'unknown';
  console.log('request', req.from.id, 'via', source);
  // 1. Greet first: the DM window closes once the request is handled
  await call('sendMessage', {
    chat_id: req.user_chat_id,
    text: 'Welcome. Tap Start below to get updates from this bot. Send /stop any time.',
    reply_markup: { inline_keyboard: [[{ text: 'Start', url: 'https://t.me/YourBot?start=' + source }]] },
  });
  // 2. Then approve
  await call('approveChatJoinRequest', { chat_id: req.chat.id, user_id: req.from.id });
}

(async function loop() {
  for (;;) {
    try {
      const r = await call('getUpdates', { offset, timeout: 30, allowed_updates: ['chat_join_request'] });
      for (const u of r.result || []) {
        offset = u.update_id + 1;
        if (u.chat_join_request) await handle(u.chat_join_request);
      }
    } catch (e) { console.error(e.message); await new Promise(r => setTimeout(r, 5000)); }
  }
})();

